 dict(kind="content", icon="🧑‍🏫", head="सर्वसमिकाएँ: हमेशा सही रहने वाले सूत्र",
      points=["जो बराबरी चर के हर मान पर सही हो = सर्वसमिका", "(x + 1)² = x² + 2x + 1 — हर x पर सही", "x + 3 = 5 — सिर्फ़ x = 2 पर (ये समीकरण है)", "सर्वसमिकाओं से गुणा और गुणनखंडन आसान"],
      say="अब बीजीय सर्वसमिकाएँ। सर्वसमिका वो बराबरी है, जो चर के हर मान पर सही रहती है। एक्स प्लस एक का वर्ग, बराबर एक्स वर्ग प्लस दो एक्स प्लस एक, ये एक्स के हर मान पर सही है। पर एक्स प्लस तीन बराबर पाँच, सिर्फ़ एक्स बराबर दो पर सही है, ये समीकरण है, सर्वसमिका नहीं।"),

